//! Original initial network identity and immutable reservation, privately
//! generated by the owning native source. A decoded frame is DATA only.
use super::*;
use crate::store::critical_namespaces::native_registry::lifecycle::founder;
use catcoms_net::{seeded_transport_identity_data, SeededTransportIdentityData};
use catcoms_wire::Encoder;

const TAG: &[u8] = b"catcoms/native-founder-network/v1\0";
const MAX_PLAIN: usize = 64 * 1024 - 40;

/// Passive original custody, not source/key/native authorization. It has no
/// path back to the runtime, issuer or transport. Net stores it on actual tasks
/// and Executor owners, NEVER on the metadata-only drain observation.
struct NativeTransportCustody {
    _work: SourceWork,
    _metadata: Arc<RuntimeMetadata>,
    _attempt: Arc<NativeTransportPayment>,
}
struct NativeTransportPayment {
    _debit: CatalogReadReservation,
}
#[derive(Clone, Copy, PartialEq, Eq)]
enum TransportBuild {
    Fresh,
    Entered,
    ObservedErr,
    Returned,
}

pub(super) struct Reservation {
    context: ([u8; 32], [u8; 32]),
    signer: [u8; 32],
    seed: Zeroizing<[u8; 32]>,
    identity: [u8; 32],
    started: bool,
    generated: bool,
    port: u16,
    public: Option<SeededTransportIdentityData>,
    seal_started: bool,
    frame: Option<Zeroizing<Vec<u8>>>,
    pending: Option<founder::Pending>,
    status: Option<crate::store::NativeCreationStatusData>,
    active: Option<crate::store::NativeCreationStatusData>,
    actual_peer: Option<String>,
    factory_started: bool,
    tcp: Option<catcoms_net::NativeTcpPreparation>,
    transport_build: TransportBuild,
    activation: Option<
        std::sync::Arc<crate::store::persistence::native_registry::network::NetworkDependency>,
    >,
    io: Option<crate::store::persistence::native_registry::network::NetworkIo>,
}
impl Reservation {
    fn new(context: ([u8; 32], [u8; 32]), signer: [u8; 32]) -> Self {
        Self {
            context,
            signer,
            seed: Zeroizing::new([0; 32]),
            identity: [0; 32],
            started: false,
            generated: false,
            port: 0,
            public: None,
            seal_started: false,
            frame: None,
            pending: None,
            status: None,
            active: None,
            actual_peer: None,
            factory_started: false,
            tcp: None,
            transport_build: TransportBuild::Fresh,
            activation: None,
            io: None,
        }
    }
    fn encode(&self, request: &NativeTextCreationRequest) -> Result<Zeroizing<Vec<u8>>, AppError> {
        let public = self.public.as_ref().ok_or_else(refused)?;
        let mut output = Encoder::with_capacity(16 * 1024);
        output.put_bytes(TAG).map_err(|_| refused())?;
        output.put_u16(1);
        for field in [
            self.context.0.as_slice(),
            self.context.1.as_slice(),
            request.invocation.as_slice(),
            request.digest.as_slice(),
            self.signer.as_slice(),
            self.identity.as_slice(),
            public.commitment_data().as_slice(),
            public.public_key_data().as_slice(),
            self.seed.as_slice(),
        ] {
            output.put_bytes(field).map_err(|_| refused())?;
        }
        // One initial publication block is reserved before transport activity.
        // Mutable restart blocks and route updates require a separate WAL.
        // Initial v1 fixes this derived port; bind failure cannot silently
        // choose another after the immutable reservation has been published.
        output.put_u16(self.port);
        output.put_u64(65_536);
        for field in [
            &request.settings.advertise,
            &request.settings.relay,
            &request.settings.rendezvous,
        ] {
            output.put_bytes(field.as_bytes()).map_err(|_| refused())?;
        }
        if output.len() > MAX_PLAIN {
            return Err(refused());
        }
        Ok(Zeroizing::new(output.finish()))
    }
}

impl<T: MeshTransport, R: CryptoRngCore> NativeTextCreationJob<T, R> {
    /// Separate Device-purpose entry from the earlier MLS-device job. There
    /// is exactly one retained seed attempt and one initial seal attempt; an
    /// unwind/unknown outcome never draws or seals a replacement on retry.
    pub fn prepare_network(
        mut self,
    ) -> Result<NativeTextCreationProgress, NativeTextCreationRefusal> {
        use NativeTextCreationRefusal as Error;
        self.require_current()?;
        let body = self.loan.body.as_mut().ok_or(Error::Unavailable)?;
        if body.network.is_none() {
            let signer = body
                .device
                .as_ref()
                .ok_or(Error::Unavailable)?
                .public_key_bytes()
                .as_slice()
                .try_into()
                .map_err(|_| Error::Unavailable)?;
            let context = body
                .work
                .native_network_context()
                .map_err(|_| Error::Storage)?;
            body.network = Some(Reservation::new(context, signer));
        }
        let network = body.network.as_mut().unwrap();
        let request = body.request.as_ref().ok_or(Error::Unavailable)?;
        let rng = body.rng.as_mut().ok_or(Error::Unavailable)?;
        let mut entered = false;
        if !network.started {
            self.keys.enter_device().map_err(|_| Error::Unavailable)?;
            entered = true;
            network.started = true;
            rng.try_fill_bytes(network.seed.as_mut())
                .map_err(|_| Error::NetworkOutcomeUnknown)?;
            rng.try_fill_bytes(&mut network.identity)
                .map_err(|_| Error::NetworkOutcomeUnknown)?;
            network.generated = true;
        }
        if !network.generated {
            return Err(Error::NetworkOutcomeUnknown);
        }
        if network.port == 0 {
            network.port = crate::store::ServerNet::derived_port_for_seed(&network.seed);
        }
        if network.public.is_none() {
            network.public = Some(
                seeded_transport_identity_data(&network.seed)
                    .map_err(|_| Error::NetworkOutcomeUnknown)?,
            );
        }
        if network.frame.is_none() {
            if network.seal_started {
                return Err(Error::NetworkOutcomeUnknown);
            }
            let plain = network.encode(request).map_err(|_| Error::Storage)?;
            let seal = body
                .work
                .prepare_native_network_seal()
                .map_err(|_| Error::Storage)?;
            // Encoding and actual mounted-key proofs precede the final native
            // check. The original seed is already cached; no sockets exist.
            self.keys.require_device().map_err(|_| Error::Unavailable)?;
            if !self.command.scope.is_open() || !self.command.ui.is_current_cached() {
                return Err(Error::Unavailable);
            }
            if !entered {
                self.keys.enter_device().map_err(|_| Error::Unavailable)?;
            }
            network.seal_started = true;
            network.frame = Some(
                seal.seal(&plain, rng)
                    .map_err(|_| Error::NetworkOutcomeUnknown)?,
            );
        }
        if network.pending.is_none() {
            network.pending = Some(founder::Pending {
                identity: network.identity,
                birth: founder::Birth {
                    kind: founder::BirthKind::NativeFounder,
                    invocation: request.invocation,
                    request: request.digest,
                    signer: network.signer,
                    network: network.public.as_ref().unwrap().commitment_data(),
                    join_context: None,
                },
                name: request.settings.server_name.clone(),
                is_dm: request.settings.is_dm,
                network_frame: network.frame.as_ref().unwrap().clone(),
            });
        }
        self.require_current()?;
        self.loan.recorded = true;
        Ok(NativeTextCreationProgress::NetworkPrepared)
    }

    /// Durable DATA only. Retain the original Pending input and actual output
    /// file across every refusal. No network/SDK installation can follow until
    /// both the covered index and same immutable file have succeeded.
    pub fn cover_pending_network(
        mut self,
    ) -> Result<NativeTextCreationProgress, NativeTextCreationRefusal> {
        use NativeTextCreationRefusal as Error;
        self.require_current()?;
        let body = self.loan.body.as_mut().ok_or(Error::Unavailable)?;
        let network = body.network.as_mut().ok_or(Error::Unavailable)?;
        let pending = network.pending.as_ref().ok_or(Error::Unavailable)?;
        let rng = body.rng.as_mut().ok_or(Error::Unavailable)?;
        if network.status.is_none() {
            network.status = Some(
                body.work
                    .birth_native_network(pending, rng)
                    .map_err(|_| Error::Storage)?,
            );
        }
        let status = network.status.unwrap();
        if status.identity != network.identity
            || status.state != crate::store::NativeCreationStateData::Pending
        {
            return Err(Error::Conflict);
        }
        let frame = network.frame.as_ref().ok_or(Error::Unavailable)?;
        if network.io.is_none() {
            network.io = Some(
                body.work
                    .prepare_native_network_io(status.id, frame)
                    .map_err(|_| Error::Storage)?,
            );
        }
        body.work
            .cover_native_network_io(network.io.as_mut().unwrap(), frame)
            .map_err(|_| Error::Storage)?;
        self.require_current()?;
        self.loan.recorded = true;
        Ok(NativeTextCreationProgress::PendingCovered)
    }

    fn require_current(&self) -> Result<(), NativeTextCreationRefusal> {
        if !self.command.scope.is_open()
            || !self.command.ui.is_current_cached()
            || self
                .loan
                .body
                .as_ref()
                .is_none_or(|body| !body.work.is_live_cached())
            || self.keys.require_device().is_err()
        {
            return Err(NativeTextCreationRefusal::Unavailable);
        }
        Ok(())
    }

    /// Move only this operation's cached resources into the concrete
    /// NativeRequired driver, then retain that WHOLE driver before advancing
    /// any SDK/journal stage. Library retry is never an alternate route.
    pub fn prepare_founder(
        mut self,
    ) -> Result<NativeTextCreationProgress, NativeTextCreationRefusal> {
        use NativeTextCreationRefusal as Error;
        self.require_current()?;
        let body = self.loan.body.as_mut().ok_or(Error::Unavailable)?;
        let network = body.network.as_mut().ok_or(Error::Unavailable)?;
        let status = network.status.ok_or(Error::Unavailable)?;
        let frame = network.frame.as_ref().ok_or(Error::Unavailable)?;
        body.work
            .cover_native_network_io(network.io.as_mut().ok_or(Error::Unavailable)?, frame)
            .map_err(|_| Error::Storage)?;
        if body.driver.is_none() {
            if network.factory_started {
                return Err(Error::NetworkOutcomeUnknown);
            }
            let request = body.request.as_ref().ok_or(Error::Unavailable)?;
            // All fallible negative checks precede taking the four inputs.
            if body.transport.is_none()
                || body.device.is_none()
                || body.group_rng.is_none()
                || body.clock.is_none()
            {
                return Err(Error::Unavailable);
            }
            network.factory_started = true;
            let inputs = crate::store::ArchiveFounderInputs::new(
                body.transport.take().unwrap(),
                body.device.take().unwrap(),
                body.group_rng.take().unwrap(),
                body.clock.take().unwrap(),
            );
            #[cfg(test)]
            tests::after_factory_input_move();
            let prepared = body.work.prepare_native_founder(
                request.invocation,
                &request.settings.display_name,
                body.founder_policy,
                inputs,
                self.keys.original.clone(),
            );
            match prepared {
                Ok(crate::store::FreshV2TextFounderBegin::Original(driver)) => {
                    body.driver = Some(driver)
                }
                other => {
                    let (inputs, error) = match other {
                        Ok(crate::store::FreshV2TextFounderBegin::Existing { inputs, .. }) => {
                            (inputs, Error::ExistingRequiresRestore)
                        }
                        Err(returned) => (returned.into_parts().0, Error::Storage),
                        Ok(crate::store::FreshV2TextFounderBegin::Original(_)) => unreachable!(),
                    };
                    let (transport, device, rng, clock) = inputs.into_parts();
                    body.transport = Some(transport);
                    body.device = Some(device);
                    body.group_rng = Some(rng);
                    body.clock = Some(clock);
                    network.factory_started = false; // concrete untouched-input refusal
                    return Err(error);
                }
            }
        }
        body.work
            .retry_native_founder(
                body.driver.as_mut().unwrap(),
                body.rng.as_mut().ok_or(Error::Unavailable)?,
                &mut self.keys,
            )
            .map_err(|_| Error::Storage)?;
        if !body.driver.as_ref().unwrap().is_ready_data() {
            return Err(Error::Storage);
        }
        if status.identity != network.identity {
            return Err(Error::Conflict);
        }
        self.require_current()?;
        self.loan.recorded = true;
        Ok(NativeTextCreationProgress::FounderPrepared)
    }

    /// Activate only the binding read from the actual retained whole driver.
    /// A decoded row, renderer binding or a second graph cannot supply it.
    pub fn cover_founder_activation(
        mut self,
    ) -> Result<NativeTextCreationProgress, NativeTextCreationRefusal> {
        use NativeTextCreationRefusal as Error;
        self.require_current()?;
        let body = self.loan.body.as_mut().ok_or(Error::Unavailable)?;
        let network = body.network.as_mut().ok_or(Error::Unavailable)?;
        let binding = body
            .driver
            .as_ref()
            .and_then(|driver| driver.binding_data())
            .ok_or(Error::Unavailable)?;
        let pending = network.pending.as_ref().ok_or(Error::Unavailable)?;
        let frame = network.frame.as_ref().ok_or(Error::Unavailable)?;
        body.work
            .cover_native_network_io(network.io.as_mut().ok_or(Error::Unavailable)?, frame)
            .map_err(|_| Error::Storage)?;
        if network.activation.is_none() {
            let expected = crate::store::persistence::native_registry::network::NetworkExpected {
                row: network.status.ok_or(Error::Unavailable)?.id,
                vault: network.context.0,
                root: network.context.1,
                identity: network.identity,
                invocation: pending.birth.invocation,
                request: pending.birth.request,
                signer: pending.birth.signer,
                network: pending.birth.network,
            };
            network.activation = Some(
                body.work
                    .prepare_native_network_dependency(
                        network.io.as_mut().unwrap(),
                        expected,
                        frame,
                        body._metadata.clone(),
                    )
                    .map_err(|_| Error::Storage)?,
            );
        }
        if binding.signer_data() != &network.signer
            || binding.vault_layout_data() != (&network.context.0, &network.context.1)
        {
            return Err(Error::Conflict);
        }
        let request = founder::Activate {
            id: network.status.ok_or(Error::Unavailable)?.id,
            identity: network.identity,
            birth: pending.birth.clone(),
            binding: super::super::super::data::FounderBindingData {
                vault: *binding.vault_layout_data().0,
                layout: *binding.vault_layout_data().1,
                group: binding.group_data().to_vec(),
                signer: *binding.signer_data(),
                source: *binding.source_data(),
                profile: *binding.profile_data(),
                pin: *binding.pin_data(),
            },
        };
        network.active = Some(
            body.work
                .activate_native_founder(
                    &request,
                    network.activation.as_ref().unwrap(),
                    body.rng.as_mut().ok_or(Error::Unavailable)?,
                )
                .map_err(|_| Error::Storage)?,
        );
        let active = network.active.unwrap();
        if active.id != request.id
            || active.identity != network.identity
            || active.state != crate::store::NativeCreationStateData::Founder
        {
            return Err(Error::Conflict);
        }
        self.require_current()?;
        self.loan.recorded = true;
        Ok(NativeTextCreationProgress::FounderStored)
    }
}

impl<R: CryptoRngCore> NativeTextCreationJob<catcoms_net::MeshService, R> {
    /// Actual concrete transport construction AFTER covered Pending and the
    /// immutable initial file. Its returned full PeerId and Phase0 identity
    /// must both match the reserved complete key before SDK creation.
    /// Accepted listen requests are not evidence of a live OS listener.
    pub fn prepare_transport(
        mut self,
    ) -> Result<NativeTextCreationProgress, NativeTextCreationRefusal> {
        use NativeTextCreationRefusal as Error;
        self.require_current()?;
        let body = self.loan.body.as_mut().ok_or(Error::Unavailable)?;
        let network = body.network.as_mut().ok_or(Error::Unavailable)?;
        if network.factory_started && body.driver.is_none() {
            return Err(Error::NetworkOutcomeUnknown);
        }
        if network.status.is_none() {
            return Err(Error::Unavailable);
        }
        body.work
            .cover_native_network_io(
                network.io.as_mut().ok_or(Error::Unavailable)?,
                network.frame.as_ref().ok_or(Error::Unavailable)?,
            )
            .map_err(|_| Error::Storage)?;
        let public = network.public.as_ref().ok_or(Error::Unavailable)?;
        if body.transport.is_none() && body.driver.is_none() {
            match network.transport_build {
                TransportBuild::Fresh => {}
                TransportBuild::ObservedErr => {
                    // This is a PROVEN local constructor Err with no returned
                    // Mesh and no SDK entry, not a general handoff refund.
                    // Its original tasks must all die before a fresh admission.
                    if !network
                        .tcp
                        .as_ref()
                        .ok_or(Error::Unavailable)?
                        .observe_drain()
                        .is_drained()
                    {
                        return Err(Error::Busy);
                    }
                    drop(network.tcp.take()); // original executor/custody, outside guards
                    network.transport_build = TransportBuild::Fresh;
                }
                TransportBuild::Entered | TransportBuild::Returned => {
                    // Neither missing cached Mesh nor CLOSED+zero can turn an
                    // unknown/returned outcome into a proven local refusal.
                    return Err(Error::NetworkOutcomeUnknown);
                }
            }
            let port = network.port;
            let listen = [
                format!("/ip4/0.0.0.0/tcp/{port}"),
                format!("/ip6/::/tcp/{port}"),
            ]
            .iter()
            .map(|address| address.parse().map_err(|_| Error::Unavailable))
            .collect::<Result<Vec<_>, _>>()?;
            #[cfg(test)]
            let listen = if tests::refuse_constructor_once() {
                let mut listen = listen;
                listen.push("/memory/1".parse().unwrap());
                listen
            } else {
                listen
            };
            let relay = &body
                .request
                .as_ref()
                .ok_or(Error::Unavailable)?
                .settings
                .relay;
            let dial = if relay.is_empty() {
                Vec::new()
            } else {
                vec![relay.parse().map_err(|_| Error::Unavailable)?]
            };
            if network.tcp.is_none() {
                // Never reuse the runtime's debit for an overlapping old task
                // allocation. Each attempt's fee follows its own metadata too.
                let attempt = Arc::new(NativeTransportPayment {
                    _debit: body
                        ._metadata
                        .pool
                        .try_reserve(catcoms_net::NATIVE_TCP_LIFETIME_BYTES)
                        .map_err(|_| Error::Busy)?,
                });
                let work = body
                    .work
                    .for_paid_runtime(&body._metadata)
                    .ok_or(Error::Unavailable)?;
                network.tcp = Some(catcoms_net::NativeTcpPreparation::new(
                    NativeTransportCustody {
                        _work: work,
                        _metadata: body._metadata.clone(),
                        _attempt: attempt.clone(),
                    },
                    attempt,
                ));
            }
            self.keys.enter_device().map_err(|_| Error::Unavailable)?;
            #[cfg(test)]
            tests::after_transport_device_entry();
            // The RT cut fences Host/UI/source counters, not independent
            // index/mount revocation. Repeat those original cached negatives
            // at actual transport admission, after all fallible preparation.
            // The entered End remains owned on refusal; no primitive is refunded.
            if !self.command.scope.is_open()
                || !self.command.ui.is_current_cached()
                || !body.work.is_live_cached()
            {
                return Err(Error::Unavailable);
            }
            let key =
                catcoms_net::keypair_from_seed(*network.seed).map_err(|_| Error::Unavailable)?;
            // Concrete Err precedes returned Mesh/SDK, but constructor dials
            // may already own key tasks. Preserve that original drain first.
            #[cfg(test)]
            tests::transport_construction();
            network.transport_build = TransportBuild::Entered;
            let built = network
                .tcp
                .as_mut()
                .unwrap()
                .build_with_port_mapping(key, &listen, &dial);
            let (transport, actual, _) = match built {
                Ok(returned) => {
                    network.transport_build = TransportBuild::Returned;
                    returned
                }
                Err(_) => {
                    // Cache the concrete result BEFORE every late negative.
                    network.transport_build = TransportBuild::ObservedErr;
                    return Err(Error::Storage);
                }
            };
            body.transport = Some(transport); // cache before every late check
            network.actual_peer = Some(actual.to_string());
        }
        if network.actual_peer.as_deref() != Some(public.peer_id_data()) {
            return Err(Error::Conflict);
        }
        if let Some(transport) = &body.transport {
            if transport.local_peer() != public.phase0_peer_data() {
                return Err(Error::Conflict);
            }
        }
        self.require_current()?;
        self.loan.recorded = true;
        Ok(NativeTextCreationProgress::TransportPrepared)
    }
}

#[cfg(test)]
mod tests;
